def solve(n, x, a):
    total = sum(a)                     # 所有数的总和
    if total < x or (total - x) % 2 != 0:
        return "-1"

    target = (total - x) // 2          # 负号部分的和
    chosen = set()
    # 从大到小贪心选择数字
    for i in range(n, 0, -1):
        if target >= i:
            target -= i
            chosen.add(i)

    if target != 0:
        return "-1"

    # 根据选择结果生成答案字符串
    ans = []
    for num in a:
        if num in chosen:
            ans.append('-')
        else:
            ans.append('+')
    return ''.join(ans)

